/*
 * A244351  Integers n such that for every integer k>0, n*6^k-1 has a divisor
 *          in the set { 7, 13, 31, 37, 97 }.
 * https://oeis.org/A244351
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = a(n-24) + 10124569 for n > 24. The first 24 terms are
 *            generated by exhaustive search; each candidate n is accepted iff
 *            for every k > 0, n*6^k - 1 is divisible by at least one of
 *            {7,13,31,37,97}
 * Range:     u8 none, u16 none, u32 n <= 24, u64 n <= 24, u128 n <= 24,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>

#define NB_PRIMES 5
#define POOL 12                     /* lcm of the orders of 6 mod the primes */

/* Pre‑computed data for the small primes */
static const int primes[NB_PRIMES] = {7, 13, 31, 37, 97};
static int pow6[NB_PRIMES][POOL + 1];
static bool pow_init = false;

/* Compute the table of 6^k (mod p) once */
static void init_pow6(void)
{
    if (pow_init) return;
    for (int i = 0; i < NB_PRIMES; ++i) {
        int p = primes[i];
        pow6[i][1] = 6 % p;
        for (int k = 2; k <= POOL; ++k)
            pow6[i][k] = (pow6[i][k-1] * 6) % p;
    }
    pow_init = true;
}

/* Check whether a 64‑bit integer satisfies the defining property.
   All arithmetic is done in 64‑bit integers, which is sufficient
   for the values that appear in the first 24 terms. */
static bool satisfies_uint64(uint64_t n)
{
    init_pow6();

    for (int k = 1; k <= POOL; ++k) {
        bool good = false;
        for (int i = 0; i < NB_PRIMES; ++i) {
            int p = primes[i];
            int nm = (int)(n % (uint64_t)p);
            int val = (int)(( (uint64_t)nm * (uint64_t)pow6[i][k] ) % (uint64_t)p);
            if (val == 1) { /* n*6^k ≡ 1 (mod p) -> p | n*6^k-1 */
                good = true;
                break;
            }
        }
        if (!good) return false;
    }
    return true;
}

/* Storage for the first 24 terms, built lazily. */
static seq_t base[24];
static unsigned int base_count = 0;
static uint64_t last_checked = 0;   /* last integer examined (uint64_t for speed) */

/* Fill the base array until it contains the first 24 terms. */
static void fill_base_if_needed(void)
{
    if (base_count >= 24) return;

    for (;;) {
        ++last_checked;
        if (satisfies_uint64(last_checked)) {
            base[base_count++] = (seq_t)last_checked;
            if (base_count >= 24) break;
        }
    }
}

/* Public function: returns the n‑th term of A244351 (n >= 1). */
seq_t a(idx_t n)
{
    /* Ensure the first 24 terms have been computed. */
    if (base_count < 24)
        fill_base_if_needed();

    if (n <= 24) {
        return base[n - 1];
    } else {
        idx_t q = (n - 1) / 24;
        idx_t r = (n - 1) % 24;          /* r ∈ {0,…,23} */
        return base[r] + (seq_t)q * 10124569;
    }
}
